package cpamp

import "math"

type ReplayMetric struct {
	Available                int     `json:"available"`
	Scored                   int     `json:"scored"`
	WAPE                     float64 `json:"wape_percent"`
	Bias                     float64 `json:"signed_bias_percent"`
	MedianAPE                float64 `json:"median_absolute_error_percent"`
	actual, absolute, signed float64
	errors                   []float64
}

func (m *ReplayMetric) add(r *ForecastResult) {
	m.Scored++
	m.actual += r.ActualUSD
	m.absolute += r.AbsoluteErrorUSD
	m.signed += r.PredictedUSD - r.ActualUSD
	m.errors = append(m.errors, math.Abs(*r.SignedErrorPercent))
}
